def run_financial_metric_registry_preview(args: argparse.Namespace) -> dict[str, Any]:
    errors = _financial_metric_registry_integrity_errors()
    filters = {
        "metric_category": args.financial_metric_registry_category or "",
        "model_critical_only": bool(args.financial_metric_registry_model_critical_only),
        "required_only": bool(args.financial_metric_registry_required_only),
    }
    metrics, aliases, validation_rules, feature_map = _filtered_financial_metric_registry(filters)
    artifacts = _financial_metric_registry_artifacts(args)
    report = _build_financial_metric_registry_report(
        metrics=metrics,
        aliases=aliases,
        validation_rules=validation_rules,
        feature_map=feature_map,
        filters=filters,
        artifacts=artifacts,
        errors=errors,
    )
    if not errors:
        try:
            if artifacts["registry_json"] is not None:
                write_json_report(report, artifacts["registry_json"])
            if artifacts["registry_csv"] is not None:
                _write_flat_csv(metrics, FINANCIAL_METRIC_REGISTRY_FIELDS, artifacts["registry_csv"])
            if artifacts["registry_markdown"] is not None:
                write_financial_metric_registry_markdown(report, artifacts["registry_markdown"])
            if artifacts["alias_csv"] is not None:
                _write_flat_csv(aliases, FINANCIAL_METRIC_ALIAS_FIELDS, artifacts["alias_csv"])
            if artifacts["validation_csv"] is not None:
                _write_flat_csv(validation_rules, FINANCIAL_METRIC_VALIDATION_RULE_FIELDS, artifacts["validation_csv"])
            if artifacts["feature_map_csv"] is not None:
                _write_flat_csv(feature_map, FINANCIAL_METRIC_FEATURE_MAP_FIELDS, artifacts["feature_map_csv"])
        except OSError as exc:
            report["status"] = "failed"
            report["errors"] = [*report["errors"], {"message": str(exc)}]
    return report


def _financial_metric_registry_artifacts(args: argparse.Namespace) -> dict[str, Path | None]:
    output_dir = args.operator_resolution_chain_output_dir
    overrides = {
        "registry_json": args.financial_metric_registry_output,
        "registry_csv": args.financial_metric_registry_csv_output,
        "registry_markdown": args.financial_metric_registry_markdown_output,
        "alias_csv": args.financial_metric_registry_alias_csv_output,
        "validation_csv": args.financial_metric_registry_validation_csv_output,
        "feature_map_csv": args.financial_metric_registry_feature_map_csv_output,
    }
    return {
        key: overrides[key] or (output_dir / file_name if output_dir is not None else None)
        for key, file_name in FINANCIAL_METRIC_REGISTRY_ARTIFACT_NAMES.items()
    }


def _filtered_financial_metric_registry(
    filters: dict[str, Any],
) -> tuple[list[dict[str, Any]], list[dict[str, Any]], list[dict[str, Any]], list[dict[str, Any]]]:
    metrics = [
        copy.deepcopy(metric)
        for metric in FINANCIAL_METRIC_REGISTRY
        if (
            not filters["metric_category"]
            or metric["metric_category"] == filters["metric_category"]
        )
        and (not filters["model_critical_only"] or metric["model_critical"])
        and (not filters["required_only"] or metric["required_for_model"])
    ]
    visible_metric_ids = {str(metric["metric_id"]) for metric in metrics}
    aliases = [
        copy.deepcopy(alias)
        for alias in FINANCIAL_METRIC_ALIAS_REGISTRY
        if alias["metric_id"] in visible_metric_ids
    ]
    filtered = bool(
        filters["metric_category"]
        or filters["model_critical_only"]
        or filters["required_only"]
    )
    validation_rules = [
        copy.deepcopy(rule)
        for rule in FINANCIAL_METRIC_VALIDATION_RULES
        if not filtered
        or visible_metric_ids.intersection(
            [*rule["required_metric_ids"], *rule["optional_metric_ids"]]
        )
    ]
    feature_map = [
        copy.deepcopy(feature)
        for feature in FINANCIAL_METRIC_FEATURE_MAP
        if not filtered
        or visible_metric_ids.intersection(
            [*feature["required_metric_ids"], *feature["optional_metric_ids"]]
        )
    ]
    return metrics, aliases, validation_rules, feature_map


def _financial_metric_registry_integrity_errors() -> list[dict[str, Any]]:
    errors: list[dict[str, Any]] = []
    metric_ids = [str(metric.get("metric_id") or "") for metric in FINANCIAL_METRIC_REGISTRY]
    metric_id_set = set(metric_ids)
    _append_registry_duplicate_errors(errors, metric_ids, "metric_id")
    for metric in FINANCIAL_METRIC_REGISTRY:
        metric_id = str(metric.get("metric_id") or "")
        checks = (
            ("metric_category", FINANCIAL_METRIC_CATEGORIES),
            ("statement_type", FINANCIAL_METRIC_STATEMENT_TYPES),
            ("metric_kind", FINANCIAL_METRIC_KINDS),
            ("period_type", FINANCIAL_METRIC_PERIOD_TYPES),
            ("expected_value_type", FINANCIAL_METRIC_VALUE_TYPES),
            ("expected_sign", FINANCIAL_METRIC_EXPECTED_SIGNS),
        )
        for field, allowed in checks:
            if metric.get(field) not in allowed:
                errors.append({"message": f"invalid_{field}:{metric_id}:{metric.get(field)}"})
        canonical_field = str(metric.get("canonical_financial_report_field") or "")
        if canonical_field and canonical_field not in FINANCIAL_METRIC_CANONICAL_REPORT_FIELDS:
            errors.append({"message": f"invalid_canonical_financial_report_field:{metric_id}:{canonical_field}"})
    for alias in FINANCIAL_METRIC_ALIAS_REGISTRY:
        if alias.get("metric_id") not in metric_id_set:
            errors.append({"message": f"unknown_alias_metric_id:{alias.get('metric_id')}"})
        if alias.get("language") not in {"en", "ru", "mixed"}:
            errors.append({"message": f"invalid_alias_language:{alias.get('metric_id')}:{alias.get('language')}"})
        if alias.get("alias_type") not in {"exact", "contains", "normalized_contains", "regex_hint"}:
            errors.append({"message": f"invalid_alias_type:{alias.get('metric_id')}:{alias.get('alias_type')}"})
    rule_ids = [str(rule.get("rule_id") or "") for rule in FINANCIAL_METRIC_VALIDATION_RULES]
    _append_registry_duplicate_errors(errors, rule_ids, "rule_id")
    feature_ids = [str(feature.get("feature_id") or "") for feature in FINANCIAL_METRIC_FEATURE_MAP]
    _append_registry_duplicate_errors(errors, feature_ids, "feature_id")
    for row_type, rows in (
        ("rule", FINANCIAL_METRIC_VALIDATION_RULES),
        ("feature", FINANCIAL_METRIC_FEATURE_MAP),
    ):
        id_field = "rule_id" if row_type == "rule" else "feature_id"
        for row in rows:
            for metric_id in [*row["required_metric_ids"], *row["optional_metric_ids"]]:
                if metric_id not in metric_id_set:
                    errors.append({"message": f"unknown_{row_type}_metric_id:{row.get(id_field)}:{metric_id}"})
    return errors


def _append_registry_duplicate_errors(
    errors: list[dict[str, Any]],
    values: list[str],
    field: str,
) -> None:
    seen: set[str] = set()
    duplicates: set[str] = set()
    for value in values:
        if not value:
            errors.append({"message": f"missing_{field}"})
        elif value in seen:
            duplicates.add(value)
        seen.add(value)
    errors.extend({"message": f"duplicate_{field}:{value}"} for value in sorted(duplicates))


def _build_financial_metric_registry_report(
    *,
    metrics: list[dict[str, Any]],
    aliases: list[dict[str, Any]],
    validation_rules: list[dict[str, Any]],
    feature_map: list[dict[str, Any]],
    filters: dict[str, Any],
    artifacts: dict[str, Path | None],
    errors: list[dict[str, Any]],
) -> dict[str, Any]:
    status = "failed" if errors else "passed"
    return {
        "status": status,
        "mode": "financial-metric-registry-preview",
        "metric_count": len(metrics),
        "alias_count": len(aliases),
        "validation_rule_count": len(validation_rules),
        "feature_count": len(feature_map),
        "required_metric_count": sum(1 for metric in metrics if metric["required_for_model"]),
        "model_critical_metric_count": sum(1 for metric in metrics if metric["model_critical"]),
        "category_counts": _count_by_key(metrics, "metric_category"),
        "statement_type_counts": _count_by_key(metrics, "statement_type"),
        "filters": filters,
        "metrics": metrics,
        "aliases": aliases,
        "validation_rules": validation_rules,
        "feature_map": feature_map,
        "artifacts": {key: _path_value(path) for key, path in artifacts.items()},
        "warnings": [],
        "errors": errors,
        "next_steps": _next_steps("financial-metric-registry-preview", status),
        "would_fetch_documents": False,
        "would_parse_documents": False,
        "would_extract_values": False,
        "would_import_report": False,
        **SAFETY_FLAGS,
    }


def run_financial_extraction_evidence_schema_preview(args: argparse.Namespace) -> dict[str, Any]:
    artifacts = _financial_extraction_evidence_schema_artifacts(args)
    registry_metrics: list[dict[str, Any]] = []
    registry_source = "in_code_registry"
    registry_input: Path | None = None
    warnings: list[dict[str, Any]] = []
    errors: list[dict[str, Any]] = []
    try:
        registry_metrics, registry_source, registry_input, registry_warnings = _resolve_financial_extraction_metric_registry(
            args
        )
        warnings.extend(registry_warnings)
    except (OSError, ValueError, json.JSONDecodeError):
        errors.append({"message": "financial_metric_registry_input_invalid"})
    if not errors and registry_input is not None:
        output_paths = [*artifacts.values(), args.json_output, args.markdown_output]
        if any(path is not None and _paths_equal(path, registry_input) for path in output_paths):
            errors.append({"message": "financial_extraction_evidence_schema_output_must_not_equal_input"})

    candidates: list[dict[str, Any]] = []
    evidence_rows: list[dict[str, Any]] = []
    normalized_facts: list[dict[str, Any]] = []
    if not errors:
        candidates, evidence_rows, normalized_facts = _build_financial_extraction_evidence_templates(registry_metrics)
        if not candidates:
            warnings.append({"message": "financial_extraction_template_metrics_unavailable"})
        errors.extend(
            _financial_extraction_evidence_schema_integrity_errors(
                registry_metrics=registry_metrics,
                candidates=candidates,
                evidence_rows=evidence_rows,
                normalized_facts=normalized_facts,
            )
        )
    report = _build_financial_extraction_evidence_schema_report(
        registry_metrics=registry_metrics,
        registry_source=registry_source,
        candidates=candidates,
        evidence_rows=evidence_rows,
        normalized_facts=normalized_facts,
        artifacts=artifacts,
        warnings=warnings,
        errors=errors,
    )
    if not errors:
        try:
            if artifacts["schema_json"] is not None:
                write_json_report(report, artifacts["schema_json"])
            if artifacts["schema_markdown"] is not None:
                write_financial_extraction_evidence_schema_markdown(report, artifacts["schema_markdown"])
            if artifacts["value_candidate_csv"] is not None:
                _write_flat_csv(
                    candidates,
                    _financial_extraction_descriptor_field_names(FINANCIAL_EXTRACTION_VALUE_CANDIDATE_FIELDS),
                    artifacts["value_candidate_csv"],
                )
            if artifacts["evidence_csv"] is not None:
                _write_flat_csv(
                    evidence_rows,
                    _financial_extraction_descriptor_field_names(FINANCIAL_EXTRACTION_EVIDENCE_FIELDS),
                    artifacts["evidence_csv"],
                )
            if artifacts["normalized_fact_csv"] is not None:
                _write_flat_csv(
                    normalized_facts,
                    _financial_extraction_descriptor_field_names(FINANCIAL_EXTRACTION_NORMALIZED_FACT_FIELDS),
                    artifacts["normalized_fact_csv"],
                )
            if artifacts["validation_status_csv"] is not None:
                _write_flat_csv(
                    FINANCIAL_EXTRACTION_VALIDATION_STATUSES,
                    FINANCIAL_EXTRACTION_VALIDATION_STATUS_FIELDS,
                    artifacts["validation_status_csv"],
                )
        except OSError as exc:
            report["status"] = "failed"
            report["errors"] = [*report["errors"], {"message": str(exc)}]
    return report


def _financial_extraction_evidence_schema_artifacts(args: argparse.Namespace) -> dict[str, Path | None]:
    output_dir = args.operator_resolution_chain_output_dir
    overrides = {
        "schema_json": args.financial_extraction_evidence_schema_output,
        "schema_markdown": args.financial_extraction_evidence_schema_markdown_output,
        "value_candidate_csv": args.financial_extraction_value_candidate_template_csv_output,
        "evidence_csv": args.financial_extraction_evidence_template_csv_output,
        "normalized_fact_csv": args.financial_extraction_normalized_fact_template_csv_output,
        "validation_status_csv": args.financial_extraction_validation_status_csv_output,
    }
    return {
        key: overrides[key] or (output_dir / file_name if output_dir is not None else None)
        for key, file_name in FINANCIAL_EXTRACTION_EVIDENCE_SCHEMA_ARTIFACT_NAMES.items()
    }


def _resolve_financial_extraction_metric_registry(
    args: argparse.Namespace,
) -> tuple[list[dict[str, Any]], str, Path | None, list[dict[str, Any]]]:
    if args.financial_metric_registry_input is not None:
        path = args.financial_metric_registry_input
        return _load_financial_extraction_metric_registry(path), str(path), path, []
    if args.operator_resolution_chain_output_dir is not None:
        path = args.operator_resolution_chain_output_dir / FINANCIAL_METRIC_REGISTRY_ARTIFACT_NAMES["registry_json"]
        if path.is_file():
            return _load_financial_extraction_metric_registry(path), str(path), path, []
        return (
            copy.deepcopy(FINANCIAL_METRIC_REGISTRY),
            "in_code_registry",
            None,
            [{"message": "financial_metric_registry_default_artifact_missing_using_in_code_registry"}],
        )
    return copy.deepcopy(FINANCIAL_METRIC_REGISTRY), "in_code_registry", None, []


def _load_financial_extraction_metric_registry(path: Path) -> list[dict[str, Any]]:
    payload = _load_json_object(path)
    metrics = payload.get("metrics")
    if not isinstance(metrics, list) or not all(isinstance(metric, dict) for metric in metrics):
        raise ValueError("financial_metric_registry_input_invalid")
    metric_ids = [str(metric.get("metric_id") or "").strip() for metric in metrics]
    if any(not metric_id for metric_id in metric_ids) or len(set(metric_ids)) != len(metric_ids):
        raise ValueError("financial_metric_registry_input_invalid")
    return copy.deepcopy(metrics)


def _financial_extraction_descriptor_field_names(descriptors: list[dict[str, Any]]) -> list[str]:
    return [str(descriptor["field_name"]) for descriptor in descriptors]


def _financial_extraction_template_row(descriptors: list[dict[str, Any]]) -> dict[str, Any]:
    return {
        str(descriptor["field_name"]): []
        if descriptor["field_type"] == "string_list"
        else False
        if descriptor["field_type"] == "boolean"
        else ""
        for descriptor in descriptors
    }


def _build_financial_extraction_evidence_templates(
    registry_metrics: list[dict[str, Any]],
) -> tuple[list[dict[str, Any]], list[dict[str, Any]], list[dict[str, Any]]]:
    registry_by_id = {str(metric.get("metric_id") or ""): metric for metric in registry_metrics}
    candidates: list[dict[str, Any]] = []
    evidence_rows: list[dict[str, Any]] = []
    normalized_facts: list[dict[str, Any]] = []
    for metric_id in FINANCIAL_EXTRACTION_TEMPLATE_METRIC_IDS:
        metric = registry_by_id.get(metric_id)
        if metric is None:
            continue
        candidate_id = f"template_candidate:{metric_id}"
        evidence_id = f"template_evidence:{metric_id}"
        fact_id = f"template_fact:{metric_id}"
        common = {
            "candidate_group_id": "template_group:financial_extraction",
            "company_id": "TEMPLATE_COMPANY_ID",
            "company_name": "TEMPLATE_COMPANY_NAME",
            "metric_id": metric_id,
            "metric_name": str(metric.get("metric_name") or metric_id),
            "canonical_financial_report_field": str(metric.get("canonical_financial_report_field") or ""),
            "document_id": "TEMPLATE_DOCUMENT_ID",
            "document_url": "TEMPLATE_DOCUMENT_URL",
            "document_sha256": "TEMPLATE_DOCUMENT_SHA256",
            "created_at_utc": "TEMPLATE_CREATED_AT_UTC",
            "created_by_mode": "financial-extraction-evidence-schema-preview",
        }
        candidate = {
            **_financial_extraction_template_row(FINANCIAL_EXTRACTION_VALUE_CANDIDATE_FIELDS),
            **common,
            "candidate_id": candidate_id,
            "metric_category": str(metric.get("metric_category") or ""),
            "statement_type": str(metric.get("statement_type") or ""),
            "raw_value_text": "TEMPLATE_VALUE",
            "normalized_value": "TEMPLATE_VALUE",
            "evidence_id": evidence_id,
            "evidence_count": 1,
            "page_number": "TEMPLATE_PAGE_NUMBER",
            "extraction_method": "template_only",
            "extraction_method_version": "template_only",
            "candidate_status": "template_only",
            "normalization_status": "template_only",
            "validation_status": "template_only",
            "validation_reason_codes": ["template_only"],
            "ready_for_validation": False,
            "ready_for_normalization": False,
            "ready_for_model_usage": False,
        }
        evidence = {
            **_financial_extraction_template_row(FINANCIAL_EXTRACTION_EVIDENCE_FIELDS),
            **common,
            "evidence_id": evidence_id,
            "candidate_id": candidate_id,
            "evidence_type": "synthetic_test_evidence",
            "evidence_locator_type": "manual_reference",
            "evidence_locator_value": "TEMPLATE_PAGE_NUMBER",
            "page_number": "TEMPLATE_PAGE_NUMBER",
            "raw_value_text": "TEMPLATE_VALUE",
            "evidence_quality_status": "template_only",
            "validation_status": "template_only",
            "validation_reason_codes": ["template_only"],
        }
        fact = {
            **_financial_extraction_template_row(FINANCIAL_EXTRACTION_NORMALIZED_FACT_FIELDS),
            **common,
            "fact_id": fact_id,
            "candidate_id": candidate_id,
            "evidence_ids": [evidence_id],
            "normalized_value": "TEMPLATE_VALUE",
            "candidate_status": "template_only",
            "normalization_status": "template_only",
            "validation_status": "template_only",
            "validation_reason_codes": ["template_only"],
            "ready_for_validation": False,
            "ready_for_normalization": False,
            "ready_for_model_usage": False,
            "ready_for_feature_builder": False,
        }
        candidates.append(candidate)
        evidence_rows.append(evidence)
        normalized_facts.append(fact)
    return candidates, evidence_rows, normalized_facts


def _financial_extraction_evidence_schema_integrity_errors(
    *,
    registry_metrics: list[dict[str, Any]],
    candidates: list[dict[str, Any]],
    evidence_rows: list[dict[str, Any]],
    normalized_facts: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    errors: list[dict[str, Any]] = []
    for schema_name, descriptors in (
        ("value_candidate", FINANCIAL_EXTRACTION_VALUE_CANDIDATE_FIELDS),
        ("evidence", FINANCIAL_EXTRACTION_EVIDENCE_FIELDS),
        ("normalized_fact", FINANCIAL_EXTRACTION_NORMALIZED_FACT_FIELDS),
    ):
        names = _financial_extraction_descriptor_field_names(descriptors)
        if len(names) != len(set(names)):
            errors.append({"message": f"duplicate_schema_field_name:{schema_name}"})
    status_ids = [str(status.get("status_id") or "") for status in FINANCIAL_EXTRACTION_VALIDATION_STATUSES]
    if any(not status_id for status_id in status_ids):
        errors.append({"message": "missing_validation_status_id"})
    if len(status_ids) != len(set(status_ids)):
        errors.append({"message": "duplicate_validation_status_id"})
    registered_statuses = set(status_ids)
    registry_metric_ids = {str(metric.get("metric_id") or "") for metric in registry_metrics}
    candidate_ids = {str(candidate.get("candidate_id") or "") for candidate in candidates}
    evidence_ids = {str(evidence.get("evidence_id") or "") for evidence in evidence_rows}
    for candidate in candidates:
        metric_id = str(candidate.get("metric_id") or "")
        if metric_id not in registry_metric_ids:
            errors.append({"message": f"unknown_template_candidate_metric_id:{metric_id}"})
        _append_financial_extraction_template_status_errors(
            errors,
            candidate,
            ("candidate_status", "normalization_status", "validation_status"),
            registered_statuses,
        )
        _append_financial_extraction_template_safety_errors(errors, "candidate", candidate)
    for evidence in evidence_rows:
        if evidence.get("candidate_id") not in candidate_ids:
            errors.append({"message": f"unknown_template_evidence_candidate_id:{evidence.get('candidate_id')}"})
        if evidence.get("evidence_type") not in FINANCIAL_EXTRACTION_EVIDENCE_TYPES:
            errors.append({"message": f"invalid_template_evidence_type:{evidence.get('evidence_type')}"})
        if evidence.get("evidence_locator_type") not in FINANCIAL_EXTRACTION_EVIDENCE_LOCATOR_TYPES:
            errors.append({"message": f"invalid_template_evidence_locator_type:{evidence.get('evidence_locator_type')}"})
        _append_financial_extraction_template_status_errors(
            errors,
            evidence,
            ("evidence_quality_status", "validation_status"),
            registered_statuses,
        )
        _append_financial_extraction_template_safety_errors(errors, "evidence", evidence)
    for fact in normalized_facts:
        if fact.get("candidate_id") not in candidate_ids:
            errors.append({"message": f"unknown_template_fact_candidate_id:{fact.get('candidate_id')}"})
        for evidence_id in fact.get("evidence_ids") or []:
            if evidence_id not in evidence_ids:
                errors.append({"message": f"unknown_template_fact_evidence_id:{evidence_id}"})
        _append_financial_extraction_template_status_errors(
            errors,
            fact,
            ("candidate_status", "normalization_status", "validation_status"),
            registered_statuses,
        )
        _append_financial_extraction_template_safety_errors(errors, "normalized_fact", fact)
    return errors


def _append_financial_extraction_template_status_errors(
    errors: list[dict[str, Any]],
    row: dict[str, Any],
    fields: tuple[str, ...],
    registered_statuses: set[str],
) -> None:
    for field in fields:
        if row.get(field) not in registered_statuses:
            errors.append({"message": f"unknown_template_status:{field}:{row.get(field)}"})


def _append_financial_extraction_template_safety_errors(
    errors: list[dict[str, Any]],
    row_type: str,
    row: dict[str, Any],
) -> None:
    for field, value in row.items():
        if (field.startswith("would_") or field.startswith("ready_")) and value is not False:
            errors.append({"message": f"unsafe_template_flag:{row_type}:{field}"})


def _build_financial_extraction_evidence_schema_report(
    *,
    registry_metrics: list[dict[str, Any]],
    registry_source: str,
    candidates: list[dict[str, Any]],
    evidence_rows: list[dict[str, Any]],
    normalized_facts: list[dict[str, Any]],
    artifacts: dict[str, Path | None],
    warnings: list[dict[str, Any]],
    errors: list[dict[str, Any]],
) -> dict[str, Any]:
    status = "failed" if errors else "warning" if warnings else "passed"
    return {
        "status": status,
        "mode": "financial-extraction-evidence-schema-preview",
        "registry_source": registry_source,
        "registry_metric_count": len(registry_metrics),
        "value_candidate_field_count": len(FINANCIAL_EXTRACTION_VALUE_CANDIDATE_FIELDS),
        "evidence_field_count": len(FINANCIAL_EXTRACTION_EVIDENCE_FIELDS),
        "normalized_fact_field_count": len(FINANCIAL_EXTRACTION_NORMALIZED_FACT_FIELDS),
        "validation_status_count": len(FINANCIAL_EXTRACTION_VALIDATION_STATUSES),
        "template_candidate_count": len(candidates),
        "template_evidence_count": len(evidence_rows),
        "template_normalized_fact_count": len(normalized_facts),
        "value_candidate_fields": copy.deepcopy(FINANCIAL_EXTRACTION_VALUE_CANDIDATE_FIELDS),
        "evidence_fields": copy.deepcopy(FINANCIAL_EXTRACTION_EVIDENCE_FIELDS),
        "normalized_fact_fields": copy.deepcopy(FINANCIAL_EXTRACTION_NORMALIZED_FACT_FIELDS),
        "validation_statuses": copy.deepcopy(FINANCIAL_EXTRACTION_VALIDATION_STATUSES),
        "template_value_candidates": candidates,
        "template_evidence_rows": evidence_rows,
        "template_normalized_facts": normalized_facts,
        "artifacts": {key: _path_value(path) for key, path in artifacts.items()},
        "warnings": warnings,
        "errors": errors,
        "next_steps": _next_steps("financial-extraction-evidence-schema-preview", status),
        "would_fetch_documents": False,
        "would_parse_documents": False,
        "would_extract_values": False,
        "would_import_report": False,
        "would_mutate_database": False,
        **SAFETY_FLAGS,
    }


def run_financial_document_artifact_retention_preview(args: argparse.Namespace) -> dict[str, Any]:
    paths = _document_artifact_retention_paths(args)
    artifacts = _document_artifact_retention_artifacts(args)
    errors = _document_artifact_retention_preflight_errors(args, paths=paths, artifacts=artifacts)
    warnings: list[dict[str, Any]] = []
    policy_rows = _build_document_artifact_retention_policy_rows(args, paths=paths)
    snapshot_rows: list[dict[str, Any]] = []
    filesystem_snapshot = _empty_document_artifact_filesystem_snapshot()
    if not errors:
        snapshot_rows = _build_document_artifact_disk_snapshot_rows(args, paths=paths)
        filesystem_snapshot, filesystem_warnings = _document_artifact_filesystem_snapshot(paths["artifact_root"])
        warnings.extend(filesystem_warnings)
    guard = _document_artifact_disk_guard(
        args,
        snapshot_rows=snapshot_rows,
        filesystem_snapshot=filesystem_snapshot,
        warnings=warnings,
    )
    cleanup_rows = _build_document_artifact_cleanup_plan_rows(args, paths=paths, snapshot_rows=snapshot_rows)
    report = _build_document_artifact_retention_report(
        args,
        policy_rows=policy_rows,
        snapshot_rows=snapshot_rows,
        cleanup_rows=cleanup_rows,
        filesystem_snapshot=filesystem_snapshot,
        guard=guard,
        artifacts=artifacts,
        warnings=warnings,
        errors=errors,
    )
    if not errors:
        try:
            if artifacts["policy_json"] is not None:
                write_json_report(report, artifacts["policy_json"])
            if artifacts["policy_csv"] is not None:
                _write_flat_csv(policy_rows, DOCUMENT_ARTIFACT_RETENTION_POLICY_FIELDS, artifacts["policy_csv"])
            if artifacts["policy_markdown"] is not None:
                write_document_artifact_retention_markdown(report, artifacts["policy_markdown"])
            if artifacts["cleanup_plan_json"] is not None:
                write_json_report(_document_artifact_cleanup_plan_report(report), artifacts["cleanup_plan_json"])
            if artifacts["cleanup_plan_csv"] is not None:
                _write_flat_csv(cleanup_rows, DOCUMENT_ARTIFACT_CLEANUP_PLAN_FIELDS, artifacts["cleanup_plan_csv"])
            if artifacts["disk_snapshot_json"] is not None:
                write_json_report(_document_artifact_disk_snapshot_report(report), artifacts["disk_snapshot_json"])
            if artifacts["disk_snapshot_csv"] is not None:
                _write_flat_csv(snapshot_rows, DOCUMENT_ARTIFACT_DISK_SNAPSHOT_FIELDS, artifacts["disk_snapshot_csv"])
        except OSError as exc:
            report["status"] = "failed"
            report["errors"] = [*report["errors"], {"message": str(exc)}]
    return report


def _document_artifact_retention_paths(args: argparse.Namespace) -> dict[str, Path]:
    return {
        "artifact_root": args.document_artifact_root_dir,
        "raw_cache": args.document_artifact_raw_cache_dir,
        "debug_quarantine": args.document_artifact_debug_quarantine_dir,
        "extraction_artifacts": args.document_artifact_extraction_artifacts_dir,
        "postgres_backups": args.document_artifact_backups_dir,
        "application_logs": args.document_artifact_logs_dir,
    }


def _document_artifact_retention_artifacts(args: argparse.Namespace) -> dict[str, Path | None]:
    output_dir = args.operator_resolution_chain_output_dir
    overrides = {
        "policy_json": args.document_artifact_retention_output,
        "policy_csv": args.document_artifact_retention_csv_output,
        "policy_markdown": args.document_artifact_retention_markdown_output,
        "cleanup_plan_json": args.document_artifact_cleanup_plan_output,
        "cleanup_plan_csv": args.document_artifact_cleanup_plan_csv_output,
        "disk_snapshot_json": args.document_artifact_disk_snapshot_output,
        "disk_snapshot_csv": args.document_artifact_disk_snapshot_csv_output,
    }
    return {
        key: overrides[key] or (output_dir / file_name if output_dir is not None else None)
        for key, file_name in DOCUMENT_ARTIFACT_RETENTION_ARTIFACT_NAMES.items()
    }


def _document_artifact_retention_preflight_errors(
    args: argparse.Namespace,
    *,
    paths: dict[str, Path],
    artifacts: dict[str, Path | None],
) -> list[dict[str, Any]]:
    errors: list[dict[str, Any]] = []
    numeric_values = {
        "document_artifact_min_free_gb": args.document_artifact_min_free_gb,
        "document_artifact_raw_cache_max_gb": args.document_artifact_raw_cache_max_gb,
        "document_artifact_debug_quarantine_max_gb": args.document_artifact_debug_quarantine_max_gb,
        "document_artifact_backups_max_gb": args.document_artifact_backups_max_gb,
        "document_artifact_logs_max_gb": args.document_artifact_logs_max_gb,
        "document_artifact_raw_cache_ttl_hours": args.document_artifact_raw_cache_ttl_hours,
        "document_artifact_debug_quarantine_ttl_hours": args.document_artifact_debug_quarantine_ttl_hours,
    }
    for name, value in numeric_values.items():
        if value < 0:
            errors.append({"message": f"invalid_document_artifact_retention_policy_value:{name}"})
    if args.document_artifact_vds_disk_limit_gb <= 0:
        errors.append({"message": "invalid_document_artifact_retention_policy_value:document_artifact_vds_disk_limit_gb"})
    if not 0 <= args.document_artifact_min_free_percent <= 100:
        errors.append({"message": "invalid_document_artifact_retention_policy_value:document_artifact_min_free_percent"})
    output_paths = [
        path
        for path in [*artifacts.values(), args.json_output, args.markdown_output]
        if path is not None
    ]
    for index, path in enumerate(output_paths):
        if any(_paths_equal(path, other) for other in output_paths[index + 1 :]):
            errors.append({"message": "document_artifact_retention_output_must_not_equal_protected_path"})
            break
    if not errors and any(
        not _document_artifact_retention_output_path_is_safe(path, protected_paths=paths)
        for path in output_paths
    ):
        errors.append({"message": "document_artifact_retention_output_must_not_equal_protected_path"})
    return errors


def _document_artifact_retention_output_path_is_safe(
    output_path: Path,
    *,
    protected_paths: dict[str, Path],
) -> bool:
    if any(_paths_equal(output_path, path) for path in protected_paths.values()):
        return False
    return not any(
        _path_is_within(output_path, protected_paths[path_role])
        for path_role in ("raw_cache", "debug_quarantine")
    )


def _path_is_within(path: Path, parent: Path) -> bool:
    try:
        path.resolve().relative_to(parent.resolve())
        return True
    except (OSError, ValueError):
        return False


