def _rzd_embedded_candidate_ranking_extract_exact_recovery_candidates(
    payloads: dict[str, Any],
) -> tuple[list[dict[str, Any]], list[dict[str, Any]], int, list[dict[str, Any]]]:
    accepted_rows: list[dict[str, Any]] = []
    invalid_rows: list[dict[str, Any]] = []
    warnings: list[dict[str, Any]] = []
    seen: set[str] = set()
    raw_count = 0
    for role, payload in payloads.items():
        for index, candidate in enumerate(_rzd_embedded_candidate_ranking_exact_recovery_candidate_dicts(payload), start=1):
            url_field, raw_url = _rzd_embedded_candidate_ranking_exact_recovery_first_value(
                candidate,
                RZD_EMBEDDED_CANDIDATE_RANKING_EXACT_RECOVERY_URL_FIELDS,
            )
            if url_field == "":
                continue
            raw_count += 1
            normalized_url, invalid_code = _rzd_embedded_candidate_ranking_exact_recovery_normalize_url(raw_url, candidate)
            row_id = hashlib.sha256(f"{role}:{index}:{raw_url}".encode("utf-8", errors="ignore")).hexdigest()[:16]
            context = _rzd_embedded_candidate_ranking_exact_recovery_context(candidate)
            if invalid_code:
                invalid_rows.append(
                    {
                        "accepted_candidate_id": f"task161_exact_recovery_invalid:{row_id}",
                        "company_id": str(candidate.get("company_id") or "18"),
                        "company_name": str(candidate.get("company_name") or "RZD"),
                        "accepted_candidate_url": "" if isinstance(raw_url, bool) else str(raw_url or ""),
                        "accepted_candidate_host": _host(str(raw_url or "")) if not isinstance(raw_url, bool) else "",
                        "candidate_origin": "task161_exact_recovery_candidate",
                        "exact_recovery_source_role": role,
                        "exact_recovery_blocker_code": invalid_code,
                    }
                )
                continue
            if normalized_url in seen:
                invalid_rows.append(
                    {
                        "accepted_candidate_id": f"task161_exact_recovery_duplicate:{row_id}",
                        "company_id": str(candidate.get("company_id") or "18"),
                        "company_name": str(candidate.get("company_name") or "RZD"),
                        "accepted_candidate_url": normalized_url,
                        "accepted_candidate_host": "company.rzd.ru",
                        "candidate_origin": "task161_exact_recovery_candidate",
                        "exact_recovery_source_role": role,
                        "exact_recovery_blocker_code": "exact_recovery_candidate_duplicate_of_task160",
                    }
                )
                continue
            seen.add(normalized_url)
            accepted_rows.append(
                _rzd_embedded_candidate_ranking_exact_recovery_accepted_row(
                    candidate,
                    normalized_url=normalized_url,
                    row_id=row_id,
                    role=role,
                    url_field=url_field,
                    context=context,
                )
            )
    if payloads and raw_count == 0:
        warnings.append({"message": "exact_recovery_no_candidate_urls_found"})
    return accepted_rows, invalid_rows, raw_count, warnings


def _rzd_embedded_candidate_ranking_exact_recovery_candidate_dicts(payload: Any) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    seen_ids: set[int] = set()

    def walk(value: Any) -> None:
        if isinstance(value, dict):
            marker = id(value)
            if marker in seen_ids:
                return
            seen_ids.add(marker)
            if any(field in value for field in RZD_EMBEDDED_CANDIDATE_RANKING_EXACT_RECOVERY_URL_FIELDS):
                rows.append(value)
            for key, child in value.items():
                if key in {"warnings", "errors", "artifacts", "next_steps"}:
                    continue
                if isinstance(child, (dict, list)):
                    walk(child)
        elif isinstance(value, list):
            for item in value:
                walk(item)

    walk(payload)
    return rows


def _rzd_embedded_candidate_ranking_exact_recovery_first_value(
    row: dict[str, Any],
    fields: tuple[str, ...],
) -> tuple[str, Any]:
    for field in fields:
        if field in row and row.get(field) not in (None, ""):
            return field, row.get(field)
    return "", ""


def _rzd_embedded_candidate_ranking_exact_recovery_normalize_url(
    value: Any,
    row: dict[str, Any],
) -> tuple[str, str]:
    if isinstance(value, bool) or value is None:
        return "", "exact_recovery_candidate_invalid_url"
    raw = str(value).strip()
    if not raw:
        return "", "exact_recovery_candidate_invalid_url"
    if raw.startswith("//"):
        raw = "https:" + raw
    elif raw.startswith("/"):
        raw = urllib.parse.urljoin("https://company.rzd.ru", raw)
    elif raw.casefold().startswith("company.rzd.ru/"):
        raw = "https://" + raw
    parsed = urllib.parse.urlparse(raw)
    if parsed.scheme != "https":
        return "", "exact_recovery_candidate_invalid_url"
    if (parsed.hostname or "").casefold() != "company.rzd.ru":
        return "", "exact_recovery_candidate_untrusted_host"
    normalized = urllib.parse.urlunparse(parsed._replace(scheme="https", netloc="company.rzd.ru", fragment=""))
    context = _rzd_embedded_candidate_ranking_exact_recovery_context(row)
    parsed = urllib.parse.urlparse(normalized)
    if _rzd_embedded_candidate_ranking_exact_recovery_is_generic_or_search(parsed, context):
        return "", "exact_recovery_candidate_generic_or_search_url"
    return normalized, ""


def _rzd_embedded_candidate_ranking_exact_recovery_is_generic_or_search(
    parsed: urllib.parse.ParseResult,
    context: str,
) -> bool:
    path = parsed.path.casefold()
    if path in {"", "/", "/ru"}:
        return True
    query_keys = set(urllib.parse.parse_qs(parsed.query, keep_blank_values=True))
    if query_keys & {"textsearch", "search_expanded", "tender_type", "status_type", "type_id", "activity_type_id"}:
        return True
    if _rzd_reporting_hub_embedded_is_media_placeholder(parsed) or _contains_any(path, ("/media/", "/static/", "/common/", "/local/", "/assets/")):
        return True
    if _rzd_embedded_candidate_ranking_short_section(parsed) and not re.search(r"20\d{2}", context):
        return True
    return False


def _rzd_embedded_candidate_ranking_exact_recovery_context(row: dict[str, Any]) -> str:
    values: list[str] = []
    for field in RZD_EMBEDDED_CANDIDATE_RANKING_EXACT_RECOVERY_CONTEXT_FIELDS:
        value = row.get(field)
        if isinstance(value, bool) or value is None:
            continue
        if isinstance(value, (list, tuple, set)):
            values.extend(str(item) for item in value if not isinstance(item, bool))
        elif isinstance(value, dict):
            values.append(json.dumps(value, ensure_ascii=False, sort_keys=True))
        else:
            values.append(str(value))
    for field, value in row.items():
        if isinstance(value, bool) or value is None:
            continue
        if any(token in field for token in ("reason", "context", "title", "note", "standard", "year", "report", "document")):
            if isinstance(value, (list, tuple, set)):
                values.extend(str(item) for item in value if not isinstance(item, bool))
            elif isinstance(value, dict):
                values.append(json.dumps(value, ensure_ascii=False, sort_keys=True))
            else:
                values.append(str(value))
    return " ".join(values).strip()


def _rzd_embedded_candidate_ranking_exact_recovery_accepted_row(
    source: dict[str, Any],
    *,
    normalized_url: str,
    row_id: str,
    role: str,
    url_field: str,
    context: str,
) -> dict[str, Any]:
    signal = urllib.parse.unquote(f"{normalized_url} {context}").casefold()
    extension = Path(urllib.parse.urlparse(normalized_url).path).suffix.casefold()
    return {
        "accepted_candidate_id": str(source.get("accepted_candidate_id") or f"task161_exact_recovery:{row_id}"),
        "embedded_candidate_id": str(source.get("embedded_candidate_id") or f"task161_exact_recovery:{row_id}"),
        "company_id": str(source.get("company_id") or "18"),
        "company_name": str(source.get("company_name") or "RZD"),
        "accepted_candidate_url": normalized_url,
        "accepted_candidate_host": "company.rzd.ru",
        "accepted_candidate_type": str(source.get("accepted_candidate_type") or "official_exact_recovery_page_candidate"),
        "accepted_candidate_source": "task161_exact_candidate_recovery_bridge",
        "accepted_candidate_status": "future_exact_candidate_validation_candidate_only",
        "candidate_origin": "task161_exact_recovery_candidate",
        "source_hub_url": str(source.get("source_hub_url") or RZD_CONTROLLED_REPORTING_HUB_FETCH_URL),
        "source_hub_sha256": str(source.get("source_hub_sha256") or ""),
        "source_hub_html_path": str(source.get("source_hub_html_path") or ""),
        "source_kind": "prior_exact_chain_artifact",
        "source_selector": role,
        "source_attribute": url_field,
        "text_context": context,
        "candidate_target_year_hint": bool(re.search(r"20\d{2}", signal)),
        "candidate_ifrs_hint": _contains_any(signal, ("ifrs", "msfo", "\u043c\u0441\u0444\u043e", "РњРЎР¤Рћ")),
        "candidate_consolidated_hint": _contains_any(signal, ("consolidated", "\u043a\u043e\u043d\u0441\u043e\u043b\u0438\u0434", "РєРѕРЅСЃРѕР»")),
        "candidate_report_hint": _contains_any(signal, ("report", "reporting", "statement", "\u043e\u0442\u0447\u0435\u0442", "\u043e\u0442\u0447\u0451\u0442", "РѕС‚С‡")),
        "candidate_annual_hint": _contains_any(signal, ("annual", "\u0433\u043e\u0434", "РіРѕРґ")),
        "candidate_accounting_standard_hint": _contains_any(signal, ("ifrs", "msfo", "\u043c\u0441\u0444\u043e", "РњРЎР¤Рћ")),
        "candidate_financial_hint": _contains_any(signal, ("financial", "finance", "\u0444\u0438\u043d\u0430\u043d\u0441", "РѕС‚С‡", "РњРЎР¤Рћ")),
        "candidate_document_file_hint": extension in {".pdf", ".xls", ".xlsx", ".zip", ".doc", ".docx"},
        "future_document_candidate_validation_required": True,
        "future_document_download_required": False,
        "future_document_parse_required": False,
        "would_fetch_candidate": False,
        "would_download_candidate": False,
        "would_parse_candidate": False,
        "would_mutate_database": False,
        "would_trigger_paper_trading": False,
    }


def _rzd_embedded_candidate_ranking_target_report_year(args: argparse.Namespace) -> int:
    year = _as_int(getattr(args, "target_report_year", 2025))
    return year if year and year > 0 else 2025


def _rzd_embedded_candidate_ranking_allowed_prior_years(args: argparse.Namespace) -> set[int]:
    raw = str(getattr(args, "allowed_prior_report_years", "") or "")
    years: set[int] = set()
    for part in raw.split(","):
        year = _as_int(part.strip())
        if year and year > 0:
            years.add(year)
    return years


def _rzd_embedded_candidate_ranking_rows(
    *,
    loaded: dict[str, Any],
    input_hashes: dict[str, str],
    target_report_year: int,
    allowed_prior_report_years: set[int],
) -> tuple[list[dict[str, Any]], list[dict[str, Any]], list[dict[str, Any]], list[dict[str, Any]], str]:
    warnings: list[dict[str, Any]] = []
    upstream_blockers = _rzd_embedded_candidate_ranking_upstream_blockers(loaded)
    if upstream_blockers:
        blocker_rows = [
            _rzd_embedded_candidate_ranking_blocker_row({}, code, ranked_candidate_id=f"task161_upstream:{index}")
            for index, code in enumerate(dict.fromkeys(upstream_blockers), start=1)
        ]
        return [], [], blocker_rows, warnings, "blocked"

    ranked_rows: list[dict[str, Any]] = []
    blocker_rows: list[dict[str, Any]] = []
    for index, accepted in enumerate(loaded["task160_accepted_rows"], start=1):
        invalid_code = _rzd_embedded_candidate_ranking_accepted_invalid_code(accepted)
        if invalid_code:
            blocker_rows.append(
                _rzd_embedded_candidate_ranking_blocker_row(
                    accepted,
                    invalid_code,
                    ranked_candidate_id=f"task161_invalid:{index}",
                )
            )
            continue
        ranked_rows.append(
            _rzd_embedded_candidate_ranking_row(
                accepted,
                index=index,
                input_hashes=input_hashes,
                target_report_year=target_report_year,
                allowed_prior_report_years=allowed_prior_report_years,
                candidate_origin="task160_embedded_candidate",
            )
        )
    for index, invalid in enumerate(loaded.get("exact_recovery_invalid_rows") or [], start=1):
        blocker_rows.append(
            _rzd_embedded_candidate_ranking_blocker_row(
                invalid,
                str(invalid.get("exact_recovery_blocker_code") or "exact_recovery_candidate_invalid_url"),
                ranked_candidate_id=f"task161_exact_recovery_invalid:{index}",
            )
        )
    for index, accepted in enumerate(loaded.get("exact_recovery_candidate_rows") or [], start=1):
        invalid_code = _rzd_embedded_candidate_ranking_accepted_invalid_code(accepted)
        if invalid_code:
            blocker_rows.append(
                _rzd_embedded_candidate_ranking_blocker_row(
                    accepted,
                    "exact_recovery_candidate_invalid_url",
                    ranked_candidate_id=f"task161_exact_recovery_invalid_accepted:{index}",
                )
            )
            continue
        ranked_rows.append(
            _rzd_embedded_candidate_ranking_row(
                accepted,
                index=index,
                input_hashes=input_hashes,
                target_report_year=target_report_year,
                allowed_prior_report_years=allowed_prior_report_years,
                candidate_origin="task161_exact_recovery_candidate",
            )
        )

    ranked_rows, duplicate_rows = _rzd_embedded_candidate_ranking_dedupe_rows(ranked_rows)
    for duplicate in duplicate_rows:
        blocker_rows.append(_rzd_embedded_candidate_ranking_blocker_row(duplicate, "exact_recovery_candidate_duplicate_of_task160"))
    ranked_rows.sort(key=lambda row: (-int(row.get("ranking_score_total") or 0), str(row.get("candidate_url") or ""), str(row.get("ranked_candidate_id") or "")))
    selected_candidates = [
        row
        for row in ranked_rows
        if row.get("confidence_tier") in {"high", "medium"}
        and row.get("ranking_class") != "unselectable_candidate"
        and row.get("year_alignment_status") in {"target_year_aligned", "prior_year_allowed"}
        and not _rzd_embedded_candidate_ranking_has_survived_hard_penalty(row)
    ][:3]
    selected_ids = {row["ranked_candidate_id"] for row in selected_candidates}
    for selection_rank, row in enumerate(selected_candidates, start=1):
        row["selection_rank"] = selection_rank
        row["selection_status"] = "selected_for_future_controlled_candidate_validation"
    for row in ranked_rows:
        if row["ranked_candidate_id"] not in selected_ids:
            row["selection_rank"] = 0
            if row.get("year_alignment_status") == "stale_year_mismatch":
                row["selection_status"] = "not_selected_stale_report_year_mismatch"
            elif row.get("year_alignment_status") == "unknown_year":
                row["selection_status"] = "not_selected_unknown_report_year"
            else:
                row["selection_status"] = "not_selected_by_ranking_threshold"

    selected_rows = [_rzd_embedded_candidate_ranking_selected_row(row) for row in selected_candidates]
    for row in ranked_rows:
        if row["ranked_candidate_id"] in selected_ids:
            continue
        blocker_code = _rzd_embedded_candidate_ranking_blocker_code_for_ranked(row)
        if blocker_code:
            blocker_rows.append(_rzd_embedded_candidate_ranking_blocker_row(row, blocker_code))

    if not loaded["task160_accepted_rows"] and not loaded.get("exact_recovery_candidate_rows"):
        blocker_rows.append(_rzd_embedded_candidate_ranking_blocker_row({}, "task160_no_accepted_candidates", ranked_candidate_id="task160_no_accepted_candidates"))
    exact_recovery_rows_available = bool(
        loaded.get("exact_recovery_candidate_rows") or loaded.get("exact_recovery_invalid_rows")
    )
    if not exact_recovery_rows_available and not selected_rows:
        blocker_rows.append(
            _rzd_embedded_candidate_ranking_blocker_row(
                {},
                "exact_recovery_artifacts_not_available",
                ranked_candidate_id="exact_recovery_artifacts_not_available",
            )
        )
    if ranked_rows and not selected_rows:
        if not any(row.get("year_alignment_status") in {"target_year_aligned", "prior_year_allowed"} for row in ranked_rows):
            blocker_rows.append(
                _rzd_embedded_candidate_ranking_blocker_row(
                    {},
                    "no_target_year_aligned_candidates",
                    ranked_candidate_id="no_target_year_aligned_candidates",
                )
            )
        if not any(row.get("blocker_code") == "only_low_confidence_candidates" for row in blocker_rows):
            blocker_rows.append(_rzd_embedded_candidate_ranking_blocker_row({}, "only_low_confidence_candidates", ranked_candidate_id="only_low_confidence_candidates"))
        blocker_rows.append(_rzd_embedded_candidate_ranking_blocker_row({}, "no_ranked_candidate_selected", ranked_candidate_id="no_ranked_candidate_selected"))

    if selected_rows and not blocker_rows and not warnings:
        status = "passed"
    elif upstream_blockers:
        status = "blocked"
    else:
        status = "warning"
    return ranked_rows, selected_rows, blocker_rows, warnings, status


def _rzd_embedded_candidate_ranking_upstream_blockers(loaded: dict[str, Any]) -> list[str]:
    blockers: list[str] = []
    inspect = loaded["task160_inspect"]
    if (
        inspect.get("status") not in {"passed", "warning"}
        or not _as_bool(inspect.get("raw_hub_html_hash_verified"))
        or not _as_bool(inspect.get("input_bytes_unchanged"))
    ):
        blockers.append("unknown_readiness")
    if any(
        _as_bool(inspect.get(field))
        for field in (
            "would_fetch_pages",
            "would_fetch_hub_pages",
            "would_download_documents",
            "would_parse_documents",
            "would_mutate_database",
            "would_trigger_paper_trading",
            "pages_fetched",
            "hub_pages_fetched",
            "documents_downloaded",
            "documents_parsed",
        )
    ):
        blockers.append("task160_upstream_safety_flags")

    candidates_payload = loaded["task160_candidates"]
    if any(
        _as_bool(candidates_payload.get(field))
        for field in ("would_fetch_pages", "would_fetch_hub_pages", "would_download_documents", "would_parse_documents", "would_mutate_database")
    ):
        blockers.append("task160_upstream_safety_flags")

    hub_fetch = loaded["task158_hub_fetch"]
    manifest = loaded["task158_hash_manifest"]
    hub_raw_sha = str(hub_fetch.get("raw_hub_html_sha256") or hub_fetch.get("raw_html_sha256") or "")
    hub_raw_path = str(hub_fetch.get("raw_hub_html_path") or hub_fetch.get("raw_html_path") or "")
    if (
        not hub_raw_path
        or not hub_raw_sha
        or hub_raw_sha != str(manifest.get("raw_html_sha256") or "")
        or int(hub_fetch.get("raw_hub_html_size_bytes") or hub_fetch.get("raw_html_size_bytes") or 0) != int(manifest.get("raw_html_size_bytes") or -1)
        or _normalize_candidate_url(str(manifest.get("final_url") or "")) != RZD_CONTROLLED_REPORTING_HUB_FETCH_URL
    ):
        blockers.append("unknown_readiness")
    if any(_as_bool(hub_fetch.get(field)) for field in ("documents_downloaded", "documents_parsed", "would_download_documents", "would_parse_documents", "would_mutate_database")):
        blockers.append("task160_upstream_safety_flags")

    task159 = loaded["task159_validation"]
    if (
        int(task159.get("self_loop_candidate_count") or 0) < 1
        or int(task159.get("accepted_candidate_count") or 0) != 0
        or not _as_bool(task159.get("no_new_document_candidate_discovered"))
    ):
        blockers.append("unknown_readiness")

    task157 = loaded["task157_plan"]
    if not (
        _as_bool(task157.get("rzd_reporting_hub_fetch_plan_ready"))
        or _as_bool(task157.get("rzd_ready_for_future_controlled_reporting_hub_fetch"))
    ):
        blockers.append("unknown_readiness")
    if _as_bool(task157.get("rzd_document_download_ready")) or _as_bool(task157.get("rzd_document_parse_ready")):
        blockers.append("task160_upstream_safety_flags")

    accepted_urls = {
        _normalize_candidate_url(str(row.get("accepted_candidate_url") or ""))
        for row in loaded["task156_accepted_candidate_rows"]
    }
    if RZD_CONTROLLED_REPORTING_HUB_FETCH_URL not in accepted_urls:
        blockers.append("unknown_readiness")

    trusted_hosts = _rzd_reporting_hub_embedded_trusted_hosts(loaded["task148_source_pack_rows"])
    if not _source_trust_recovery_draft_review_host_trusted("company.rzd.ru", trusted_hosts):
        blockers.append("unknown_readiness")
    return blockers


def _rzd_embedded_candidate_ranking_accepted_invalid_code(row: dict[str, Any]) -> str:
    candidate_url = row.get("accepted_candidate_url")
    candidate_host = row.get("accepted_candidate_host")
    if isinstance(candidate_url, bool) or isinstance(candidate_host, bool):
        return "task160_accepted_candidate_invalid"
    candidate_url_text = str(candidate_url or "").strip()
    candidate_host_text = str(candidate_host or "").strip().casefold()
    if not candidate_url_text or candidate_host_text != "company.rzd.ru":
        return "task160_accepted_candidate_invalid"
    if row.get("accepted_candidate_status") not in {
        "future_embedded_document_candidate_validation_candidate_only",
        "future_exact_candidate_validation_candidate_only",
    }:
        return "task160_accepted_candidate_invalid"
    if not _as_bool(row.get("future_document_candidate_validation_required")):
        return "task160_accepted_candidate_invalid"
    if any(
        _as_bool(row.get(field))
        for field in (
            "future_document_download_required",
            "future_document_parse_required",
            "would_fetch_candidate",
            "would_download_candidate",
            "would_parse_candidate",
            "would_mutate_document_intake",
            "would_mutate_database",
            "would_extract_values",
            "would_import_report",
            "would_mutate_scores",
            "would_trigger_paper_trading",
            "would_delete_files",
        )
    ):
        return "task160_accepted_candidate_invalid"
    parsed = urllib.parse.urlparse(candidate_url_text)
    signal = urllib.parse.unquote(candidate_url_text).casefold()
    if parsed.scheme not in {"http", "https"} or _host(candidate_url_text) != "company.rzd.ru":
        return "task160_accepted_candidate_invalid"
    return ""


def _rzd_embedded_candidate_ranking_year_alignment(
    accepted: dict[str, Any],
    *,
    candidate_url: str,
    target_report_year: int,
    allowed_prior_report_years: set[int],
) -> dict[str, Any]:
    detected_years = _rzd_embedded_candidate_ranking_detect_years(accepted, candidate_url=candidate_url)
    primary_year = 0
    status = "unknown_year"
    reason_codes: list[str] = []
    target_aligned = target_report_year in detected_years
    allowed_prior = sorted(year for year in detected_years if year in allowed_prior_report_years)
    prior_candidate = any(year < target_report_year for year in detected_years)
    stale = False
    unknown = False
    if target_aligned:
        primary_year = target_report_year
        status = "target_year_aligned"
        reason_codes.append("target_report_year_aligned")
    elif allowed_prior:
        primary_year = allowed_prior[-1]
        status = "prior_year_allowed"
        prior_candidate = True
        reason_codes.append("prior_report_year_allowed")
    elif detected_years:
        primary_year = max(detected_years)
        status = "stale_year_mismatch"
        stale = True
        reason_codes.append("stale_report_year_mismatch")
    else:
        unknown = True
        reason_codes.append("unknown_report_year")
    return {
        "target_report_year": target_report_year,
        "detected_report_years": detected_years,
        "primary_detected_report_year": primary_year,
        "target_year_aligned": target_aligned,
        "prior_year_candidate": prior_candidate,
        "stale_year_mismatch": stale,
        "unknown_year_candidate": unknown,
        "year_alignment_status": status,
        "year_alignment_reason_codes": reason_codes,
    }


def _rzd_embedded_candidate_ranking_detect_years(
    accepted: dict[str, Any],
    *,
    candidate_url: str,
) -> list[int]:
    texts = _rzd_embedded_candidate_ranking_year_evidence_texts(accepted, candidate_url=candidate_url)
    years: set[int] = set()
    for text in texts:
        for match in re.finditer(r"(?<!\d)(20\d{2})(?!\d)", text):
            year = _as_int(match.group(1))
            if year and 2000 <= year <= 2100:
                years.add(year)
        for match in re.finditer(r"(?<!\d)(2[0-9])\s*(?:год(?:а|у|ом)?|г\.?|year|fy)\b", text, flags=re.IGNORECASE):
            year = 2000 + int(match.group(1))
            if 2000 <= year <= 2100:
                years.add(year)
    normalized_url = _normalize_candidate_url(candidate_url)
    parsed = urllib.parse.urlparse(normalized_url)
    if normalized_url == RZD_EXACT_DOCUMENT_DEFAULT_URL or (
        parsed.path.casefold() == "/ru/9397/page/104069" and re.search(r"(?:^|&)id=322745(?:&|$)", parsed.query)
    ):
        years.add(2025)
    return sorted(years)


def _rzd_embedded_candidate_ranking_year_evidence_texts(
    accepted: dict[str, Any],
    *,
    candidate_url: str,
) -> list[str]:
    texts: list[str] = [candidate_url, str(accepted.get("accepted_candidate_url") or "")]
    preferred_fields = (
        "source_kind",
        "source_selector",
        "source_attribute",
        "raw_value",
        "decoded_value",
        "text_context",
        "local_context",
        "merged_context",
        "candidate_link_text",
        "candidate_title",
        "accepted_candidate_type",
        "accepted_candidate_source",
        "ranking_reason_codes",
    )
    for field in preferred_fields:
        value = accepted.get(field)
        if isinstance(value, bool) or value is None:
            continue
        if isinstance(value, (list, tuple, set)):
            texts.extend(str(item) for item in value if not isinstance(item, bool))
        elif isinstance(value, dict):
            texts.append(json.dumps(value, ensure_ascii=False, sort_keys=True))
        else:
            texts.append(str(value))
    for field, value in accepted.items():
        if field in preferred_fields or isinstance(value, bool) or value is None:
            continue
        if any(token in field for token in ("context", "reason", "title", "text", "raw", "decoded", "source", "selector", "attribute", "url")):
            if isinstance(value, (list, tuple, set)):
                texts.extend(str(item) for item in value if not isinstance(item, bool))
            elif isinstance(value, dict):
                texts.append(json.dumps(value, ensure_ascii=False, sort_keys=True))
            else:
                texts.append(str(value))
    return [urllib.parse.unquote(text).casefold() for text in texts if text]


def _rzd_embedded_candidate_ranking_row(
    accepted: dict[str, Any],
    *,
    index: int,
    input_hashes: dict[str, str],
    target_report_year: int,
    allowed_prior_report_years: set[int],
    candidate_origin: str,
) -> dict[str, Any]:
    candidate_url = _normalize_candidate_url(str(accepted.get("accepted_candidate_url") or ""))
    candidate_host = _host(candidate_url)
    parsed = urllib.parse.urlparse(candidate_url)
    extension = Path(parsed.path).suffix.casefold()
    source_kind = str(accepted.get("source_kind") or "")
    hints = {
        "candidate_target_year_hint": _as_bool(accepted.get("candidate_target_year_hint")),
        "candidate_ifrs_hint": _as_bool(accepted.get("candidate_ifrs_hint")),
        "candidate_consolidated_hint": _as_bool(accepted.get("candidate_consolidated_hint")),
        "candidate_report_hint": _as_bool(accepted.get("candidate_report_hint")),
        "candidate_annual_hint": _as_bool(accepted.get("candidate_annual_hint")),
        "candidate_accounting_standard_hint": _as_bool(accepted.get("candidate_accounting_standard_hint")),
        "candidate_financial_hint": _as_bool(accepted.get("candidate_financial_hint")),
        "candidate_document_file_hint": _as_bool(accepted.get("candidate_document_file_hint")),
    }
    year_alignment = _rzd_embedded_candidate_ranking_year_alignment(
        accepted,
        candidate_url=candidate_url,
        target_report_year=target_report_year,
        allowed_prior_report_years=allowed_prior_report_years,
    )
    scores, reason_codes, penalty_codes = _rzd_embedded_candidate_ranking_score(
        candidate_url=candidate_url,
        extension=extension,
        source_kind=source_kind,
        hints=hints,
        year_alignment=year_alignment,
    )
    if candidate_origin == "task161_exact_recovery_candidate":
        reason_codes.append("exact_candidate_recovered_from_prior_chain")
    total = sum(scores.values())
    confidence = _rzd_embedded_candidate_ranking_confidence(total)
    ranking_class = _rzd_embedded_candidate_ranking_class(
        candidate_url=candidate_url,
        extension=extension,
        confidence=confidence,
        hints=hints,
        penalty_codes=penalty_codes,
    )
    year_selectable = year_alignment.get("year_alignment_status") in {"target_year_aligned", "prior_year_allowed"}
    ranked_id = f"rzd_embedded_candidate_ranking:{hashlib.sha256(candidate_url.encode('utf-8')).hexdigest()[:16]}"
    row = {
        "ranked_candidate_id": ranked_id,
        "accepted_candidate_id": str(accepted.get("accepted_candidate_id") or f"task160_accepted:{index}"),
        "embedded_candidate_id": str(accepted.get("embedded_candidate_id") or ""),
        "company_id": str(accepted.get("company_id") or "18"),
        "company_name": str(accepted.get("company_name") or "RZD"),
        "candidate_url": candidate_url,
        "candidate_host": candidate_host,
        "candidate_type": str(accepted.get("accepted_candidate_type") or ""),
        "candidate_source": str(accepted.get("accepted_candidate_source") or "task160_embedded_report_link_inspect"),
        "candidate_origin": candidate_origin,
        "candidate_status": str(accepted.get("accepted_candidate_status") or ""),
        "source_hub_url": str(accepted.get("source_hub_url") or RZD_CONTROLLED_REPORTING_HUB_FETCH_URL),
        "source_hub_sha256": str(accepted.get("source_hub_sha256") or input_hashes.get("task158_hash_manifest") or ""),
        "source_hub_html_path": str(accepted.get("source_hub_html_path") or ""),
        "source_kind": source_kind,
        "source_selector": str(accepted.get("source_selector") or ""),
        "source_attribute": str(accepted.get("source_attribute") or ""),
        **hints,
        "ranking_score_total": total,
        "ranking_score_url_pattern": scores["ranking_score_url_pattern"],
        "ranking_score_context": scores["ranking_score_context"],
        "ranking_score_document_signal": scores["ranking_score_document_signal"],
        "ranking_score_accounting_signal": scores["ranking_score_accounting_signal"],
        "ranking_score_year_signal": scores["ranking_score_year_signal"],
        "ranking_score_year_alignment": scores["ranking_score_year_alignment"],
        "ranking_score_penalty": scores["ranking_score_penalty"],
        **year_alignment,
        "ranking_reason_codes": reason_codes,
        "ranking_penalty_codes": penalty_codes,
        "ranking_class": ranking_class,
        "confidence_tier": confidence,
        "selection_rank": 0,
        "selection_status": "not_selected_by_ranking_threshold",
        "future_controlled_candidate_validation_required": confidence in {"high", "medium"} and year_selectable,
        "future_candidate_fetch_plan_required": confidence in {"high", "medium"} and year_selectable,
        "future_document_download_required": False,
        "future_document_parse_required": False,
        "future_import_required": False,
        "future_scoring_required": False,
        "future_paper_trading_required": False,
        "would_fetch_candidate": False,
        "would_fetch_page": False,
        "would_download_candidate": False,
        "would_parse_candidate": False,
        "would_mutate_document_intake": False,
        "would_mutate_database": False,
        "would_extract_values": False,
        "would_import_report": False,
        "would_mutate_scores": False,
        "would_trigger_paper_trading": False,
        "would_delete_files": False,
    }
    for field in RZD_EMBEDDED_CANDIDATE_RANKING_ROW_BOOL_FIELDS:
        row[field] = bool(row.get(field))
    return row


def _rzd_embedded_candidate_ranking_score(
    *,
    candidate_url: str,
    extension: str,
    source_kind: str,
    hints: dict[str, bool],
    year_alignment: dict[str, Any],
) -> tuple[dict[str, int], list[str], list[str]]:
    scores = {
        "ranking_score_url_pattern": 0,
        "ranking_score_context": 0,
        "ranking_score_document_signal": 0,
        "ranking_score_accounting_signal": 0,
        "ranking_score_year_signal": 0,
        "ranking_score_year_alignment": 0,
        "ranking_score_penalty": 0,
    }
    reason_codes: list[str] = []
    penalty_codes: list[str] = []
    parsed = urllib.parse.urlparse(candidate_url)
    path = parsed.path.casefold()
    query = parsed.query.casefold()
    if extension == ".pdf":
        scores["ranking_score_document_signal"] += 50
        reason_codes.append("direct_pdf_document_candidate")
    elif extension in {".xls", ".xlsx"}:
        scores["ranking_score_document_signal"] += 40
        reason_codes.append("direct_spreadsheet_candidate")
    elif extension in {".zip", ".doc", ".docx"}:
        scores["ranking_score_document_signal"] += 30
        reason_codes.append("direct_document_archive_candidate")
    if hints["candidate_ifrs_hint"]:
        scores["ranking_score_accounting_signal"] += 20
        reason_codes.append("ifrs_context")
    if hints["candidate_consolidated_hint"]:
        scores["ranking_score_accounting_signal"] += 15
        reason_codes.append("consolidated_context")
    if hints["candidate_target_year_hint"]:
        scores["ranking_score_year_signal"] += 15
        reason_codes.append("target_year_context")
    if hints["candidate_report_hint"]:
        scores["ranking_score_context"] += 15
        reason_codes.append("report_context")
    if hints["candidate_annual_hint"]:
        scores["ranking_score_context"] += 10
        reason_codes.append("annual_context")
    if hints["candidate_financial_hint"]:
        scores["ranking_score_context"] += 10
        reason_codes.append("financial_context")
    if hints["candidate_accounting_standard_hint"]:
        scores["ranking_score_accounting_signal"] += 10
        reason_codes.append("accounting_standard_context")
    if re.fullmatch(r"/ru/\d+/page/\d+", path) and re.search(r"(?:^|&)id=\d+(?:&|$)", query):
        scores["ranking_score_url_pattern"] += 25
        reason_codes.append("rzd_cms_report_page_shape")
    if source_kind in {"script", "data_attribute", "value", "attribute", "event_attribute", "hidden_value"}:
        scores["ranking_score_context"] += 15
        reason_codes.append("structured_embedded_source")
    if any(hints[field] for field in ("candidate_report_hint", "candidate_ifrs_hint", "candidate_target_year_hint", "candidate_accounting_standard_hint", "candidate_annual_hint")):
        scores["ranking_score_context"] += 10
        reason_codes.append("local_report_accounting_year_context")
    if _normalize_candidate_url(candidate_url) == RZD_EXACT_DOCUMENT_DEFAULT_URL or (
        "/ru/9397/page/104069" in path and "id=322745" in query
    ):
        scores["ranking_score_url_pattern"] += 15
        reason_codes.append("known_rzd_2025_candidate_shape")

    year_reason_codes = [str(code) for code in year_alignment.get("year_alignment_reason_codes") or []]
    if year_alignment.get("target_year_aligned"):
        scores["ranking_score_year_alignment"] += 25
        reason_codes.append("target_report_year_aligned")
    elif year_alignment.get("year_alignment_status") == "prior_year_allowed":
        reason_codes.append("prior_report_year_allowed")
    elif year_alignment.get("stale_year_mismatch"):
        scores["ranking_score_year_alignment"] -= 80
        penalty_codes.append("stale_report_year_mismatch")
    elif year_alignment.get("unknown_year_candidate"):
        scores["ranking_score_year_alignment"] -= 30
        penalty_codes.append("unknown_report_year")
    for code in year_reason_codes:
        if code not in reason_codes and code not in {"stale_report_year_mismatch", "unknown_report_year"}:
            reason_codes.append(code)

    if source_kind == "raw_text" and not any(hints[field] for field in ("candidate_report_hint", "candidate_ifrs_hint", "candidate_target_year_hint", "candidate_accounting_standard_hint")):
        scores["ranking_score_penalty"] -= 40
        penalty_codes.append("raw_text_without_strong_local_context")
    if _rzd_embedded_candidate_ranking_short_section(parsed):
        scores["ranking_score_penalty"] -= 30
        penalty_codes.append("short_section_only")
    if hints["candidate_financial_hint"] and not any(
        hints[field]
        for field in (
            "candidate_report_hint",
            "candidate_ifrs_hint",
            "candidate_consolidated_hint",
            "candidate_target_year_hint",
            "candidate_annual_hint",
        )
    ):
        scores["ranking_score_penalty"] -= 30
        penalty_codes.append("financial_hint_only")
    if _rzd_reporting_hub_embedded_is_generic_navigation(parsed, ""):
        scores["ranking_score_penalty"] -= 50
        penalty_codes.append("generic_navigation_survived")
    if _rzd_reporting_hub_embedded_is_media_placeholder(parsed):
        scores["ranking_score_penalty"] -= 50
        penalty_codes.append("media_placeholder_survived")
    query_keys = set(urllib.parse.parse_qs(parsed.query, keep_blank_values=True))
    if "editor" in query_keys:
        scores["ranking_score_penalty"] -= 25
        penalty_codes.append("editor_like_query")
    if query_keys & {"textsearch", "search_expanded", "tender_type", "status_type", "type_id"}:
        scores["ranking_score_penalty"] -= 25
        penalty_codes.append("search_or_filter_survived")
    if _contains_any(path, ("/media/", "/static/", "/common/", "/local/", "/assets/")):
        scores["ranking_score_penalty"] -= 25
        penalty_codes.append("static_or_media_asset")
    return scores, reason_codes, penalty_codes


def _rzd_embedded_candidate_ranking_short_section(parsed: urllib.parse.ParseResult) -> bool:
    segments = [segment for segment in parsed.path.strip("/").split("/") if segment]
    return len(segments) == 2 and segments[0] == "ru" and segments[1].isdigit()


def _rzd_embedded_candidate_ranking_dedupe_rows(
    rows: list[dict[str, Any]],
) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    by_url: dict[str, dict[str, Any]] = {}
    duplicates: list[dict[str, Any]] = []
    for row in rows:
        url = str(row.get("candidate_url") or "")
        existing = by_url.get(url)
        if existing is None:
            by_url[url] = row
            continue
        keep = _rzd_embedded_candidate_ranking_prefer_row(existing, row)
        discard = row if keep is existing else existing
        if (
            row.get("candidate_origin") == "task161_exact_recovery_candidate"
            or existing.get("candidate_origin") == "task161_exact_recovery_candidate"
        ):
            for target in (keep, discard):
                reason_codes = list(target.get("ranking_reason_codes") or [])
                if "exact_recovery_candidate_duplicate_of_task160" not in reason_codes:
                    reason_codes.append("exact_recovery_candidate_duplicate_of_task160")
                target["ranking_reason_codes"] = reason_codes
        by_url[url] = keep
        duplicates.append(discard)
    return list(by_url.values()), duplicates


def _rzd_embedded_candidate_ranking_prefer_row(existing: dict[str, Any], candidate: dict[str, Any]) -> dict[str, Any]:
    def key(row: dict[str, Any]) -> tuple[int, int, int, int]:
        return (
            1 if row.get("target_year_aligned") is True else 0,
            1 if row.get("candidate_origin") == "task161_exact_recovery_candidate" else 0,
            int(row.get("ranking_score_total") or 0),
            1 if row.get("year_alignment_status") == "prior_year_allowed" else 0,
        )

    return candidate if key(candidate) > key(existing) else existing


def _rzd_embedded_candidate_ranking_confidence(score: int) -> str:
    if score >= 70:
        return "high"
    if score >= 45:
        return "medium"
    if score >= 20:
        return "low"
    return "reject"


def _rzd_embedded_candidate_ranking_class(
    *,
    candidate_url: str,
    extension: str,
    confidence: str,
    hints: dict[str, bool],
    penalty_codes: list[str],
) -> str:
    parsed = urllib.parse.urlparse(candidate_url)
    if extension in {".pdf", ".xls", ".xlsx", ".zip", ".doc", ".docx"} and confidence == "high":
        return "direct_document_high_confidence"
    if re.fullmatch(r"/ru/\d+/page/\d+", parsed.path.casefold()) and re.search(r"(?:^|&)id=\d+(?:&|$)", parsed.query.casefold()):
        if confidence == "high":
            return "report_page_high_confidence"
        if confidence == "medium":
            return "report_page_medium_confidence"
    if "financial_hint_only" in penalty_codes or (hints["candidate_financial_hint"] and confidence == "low"):
        return "financial_section_low_confidence"
    if hints["candidate_financial_hint"] and confidence == "reject":
        return "ambiguous_finance_only"
    if confidence in {"high", "medium"} and hints["candidate_report_hint"]:
        return "report_page_high_confidence" if confidence == "high" else "report_page_medium_confidence"
    return "unselectable_candidate"


def _rzd_embedded_candidate_ranking_has_survived_hard_penalty(row: dict[str, Any]) -> bool:
    penalties = set(row.get("ranking_penalty_codes") or [])
    return bool(penalties & {"generic_navigation_survived", "search_or_filter_survived", "media_placeholder_survived", "financial_hint_only"})


