def _rzd_controlled_value_extraction_statement_title_match(
    target_type: str,
    text: str,
    page_row: dict[str, Any],
) -> dict[str, Any]:
    target_type = str(target_type or "")
    title_terms_by_type = _rzd_controlled_value_extraction_statement_title_term_map()
    target_terms = title_terms_by_type.get(target_type, (target_type.replace("_", " "),))
    metadata_lines = [
        str(page_row.get("detected_section_type") or ""),
        str(page_row.get("detected_section_title") or ""),
    ]
    text_lines = [line.strip() for line in str(text or "").splitlines() if line.strip()]
    title_zone_lines = text_lines[:12]
    candidate_lines = [line for line in metadata_lines if line] + title_zone_lines

    def _line_has_terms(line: str, terms: Sequence[str]) -> bool:
        prepared = _normalize_pdf_preview_text_for_signal_detection(line)
        return any(
            _rzd_manual_official_pdf_phrase_found(str(term), prepared["normalized_text"], prepared["compact_text"])
            for term in terms
        )

    matched_title = ""
    matched_title_line_number = 0
    target_title_matched = False
    body_reference_title_rejected_count = 0
    clean_page_metadata_match = (
        (page_row.get("detected_section_type") == target_type or _as_bool(page_row.get(f"is_{target_type}_page")))
        and not _rzd_controlled_value_extraction_page_is_disallowed_primary(page_row, allow_notes=False)
    )
    if clean_page_metadata_match:
        target_title_matched = True
        matched_title = str(page_row.get("detected_section_title") or page_row.get("detected_section_type") or target_type)
        matched_title_line_number = 0
    for offset, line in enumerate(title_zone_lines, start=1):
        if _line_has_terms(line, target_terms):
            if _rzd_controlled_value_extraction_is_heading_like_title_line(line):
                target_title_matched = True
                matched_title = line[:240]
                matched_title_line_number = offset
                break
            body_reference_title_rejected_count += 1
    if not target_title_matched:
        for offset, line in enumerate(text_lines[12:40], start=13):
            if _line_has_terms(line, target_terms):
                body_reference_title_rejected_count += 1
                break
    if not target_title_matched and not body_reference_title_rejected_count:
        for line in metadata_lines:
            if line and _line_has_terms(line, target_terms):
                if not _rzd_controlled_value_extraction_is_statement_body_reference(line):
                    target_title_matched = True
                    matched_title = line[:240]
                    matched_title_line_number = 0
                    break
                body_reference_title_rejected_count += 1

    cross_target_title_type = ""
    detected_type = str(page_row.get("detected_section_type") or "")
    if detected_type and detected_type in title_terms_by_type and detected_type != target_type:
        cross_target_title_type = detected_type
    for other_type in title_terms_by_type:
        if other_type == target_type:
            continue
        if _as_bool(page_row.get(f"is_{other_type}_page")):
            cross_target_title_type = other_type
            break
    if not cross_target_title_type:
        for other_type, other_terms in title_terms_by_type.items():
            if other_type == target_type:
                continue
            for line in candidate_lines:
                if _line_has_terms(line, other_terms):
                    cross_target_title_type = other_type
                    break
            if cross_target_title_type:
                break
    if target_type == "profit_or_loss" and _rzd_controlled_value_extraction_is_tax_note_context(text, page_row):
        cross_target_title_type = "tax_notes"
    if target_type == "cash_flows" and _as_bool(page_row.get("is_notes_page")):
        cross_target_title_type = "notes_general"

    cross_target_title_detected = bool(cross_target_title_type)
    reason_codes: list[str] = []
    reject_codes: list[str] = []
    if target_title_matched:
        reason_codes.append("target_statement_title_matched")
    else:
        reject_codes.append("target_statement_title_missing")
    if body_reference_title_rejected_count:
        reject_codes.append("body_reference_title_rejected")
    if cross_target_title_detected:
        reject_codes.append("controlled_value_extraction_cross_target_page_rejected")
    return {
        "target_title_matched": bool(target_title_matched),
        "matched_title": str(matched_title or ""),
        "matched_title_line_number": int(matched_title_line_number or 0),
        "cross_target_title_detected": bool(cross_target_title_detected),
        "cross_target_title_type": str(cross_target_title_type or ""),
        "title_match_reason_codes": reason_codes,
        "title_reject_reason_codes": reject_codes,
        "body_reference_title_rejected_count": int(body_reference_title_rejected_count),
    }


def _rzd_controlled_value_extraction_page_title(target_type: str, text: str, page_row: dict[str, Any]) -> str:
    detected = str(page_row.get("detected_section_title") or "").strip()
    if detected and detected != target_type:
        return detected[:240]
    title_terms = {
        "statement_of_financial_position": ("financial position", "отчет о финансовом положении"),
        "profit_or_loss": ("profit or loss", "прибылях и убытках"),
        "other_comprehensive_income": ("comprehensive income", "совокупном доходе", "прочий совокупный доход"),
        "cash_flows": ("cash flows", "движении денежных средств"),
    }.get(target_type, (target_type.replace("_", " "),))
    for line in str(text or "").splitlines()[:12]:
        prepared = _normalize_pdf_preview_text_for_signal_detection(line)
        if any(_rzd_manual_official_pdf_phrase_found(term, prepared["normalized_text"], prepared["compact_text"]) for term in title_terms):
            return line.strip()[:240]
    return detected[:240]


def _rzd_controlled_value_extraction_numeric_groups(line: str) -> list[tuple[str, int | None]]:
    groups: list[tuple[str, int | None]] = []
    for match in re.finditer(r"\(?-?\d+(?:[,.]\d+)?\)?|[вЂ”вЂ“-]", str(line or "")):
        raw = match.group(0).strip()
        value = _rzd_manual_official_pdf_controlled_value_extraction_number_token_to_int(raw)
        if value is not None:
            groups.append((raw, value))
    return groups


def _rzd_controlled_value_extraction_is_wide_equity_movement_line(line: str) -> bool:
    text = str(line or "")
    dash_count = len(re.findall(r"[—–-]|вЂ”|вЂ“", text))
    numeric_group_count = len(_rzd_controlled_value_extraction_numeric_groups(text))
    prepared = _normalize_pdf_preview_text_for_signal_detection(text)
    equity_terms = (
        "changes in equity",
        "equity movement",
        "РёР·РјРµРЅРµРЅРёСЏС… РєР°РїРёС‚Р°Р»Р°",
        "РєР°РїРёС‚Р°Р»Р°",
    )
    has_equity_context = any(
        _rzd_manual_official_pdf_phrase_found(term, prepared["normalized_text"], prepared["compact_text"])
        for term in equity_terms
    )
    return bool((dash_count >= 4 and numeric_group_count > 4) or (has_equity_context and numeric_group_count > 4))


def _rzd_controlled_value_extraction_combine_numeric_groups(groups: Sequence[tuple[str, int | None]]) -> tuple[str, int | None]:
    raw = " ".join(str(item[0]).strip() for item in groups if str(item[0]).strip())
    if not raw:
        return "", None
    negative = raw.strip().startswith("(") and raw.strip().endswith(")")
    digits = "".join(re.findall(r"\d+", raw))
    if not digits:
        return raw, None
    value = int(digits)
    return raw, -value if negative else value


def _rzd_controlled_value_extraction_value_columns(line: str) -> dict[str, Any]:
    grouped_numbers = _rzd_manual_official_pdf_controlled_value_extraction_line_numbers(line)
    simple_groups = _rzd_controlled_value_extraction_numeric_groups(line)
    if len(simple_groups) >= 3 and simple_groups[0][1] is not None and 0 < abs(int(simple_groups[0][1])) <= 99:
        remaining = list(simple_groups[1:])
        if len(remaining) == 2:
            raw_2025, value_2025 = remaining[0]
            raw_2024, value_2024 = remaining[1]
            return {"raw_2025": raw_2025, "value_2025": value_2025, "raw_2024": raw_2024, "value_2024": value_2024, "note_reference": simple_groups[0][0]}
        if len(remaining) >= 4 and len(remaining) % 2 == 0 and all(abs(int(item[1] or 0)) <= 999 for item in remaining):
            half = len(remaining) // 2
            raw_2025, value_2025 = _rzd_controlled_value_extraction_combine_numeric_groups(remaining[:half])
            raw_2024, value_2024 = _rzd_controlled_value_extraction_combine_numeric_groups(remaining[half:])
            return {"raw_2025": raw_2025, "value_2025": value_2025, "raw_2024": raw_2024, "value_2024": value_2024, "note_reference": simple_groups[0][0]}
    if len(simple_groups) >= 4 and len(simple_groups) % 2 == 0 and all(abs(int(item[1] or 0)) <= 999 for item in simple_groups):
        half = len(simple_groups) // 2
        raw_2025, value_2025 = _rzd_controlled_value_extraction_combine_numeric_groups(simple_groups[:half])
        raw_2024, value_2024 = _rzd_controlled_value_extraction_combine_numeric_groups(simple_groups[half:])
        return {"raw_2025": raw_2025, "value_2025": value_2025, "raw_2024": raw_2024, "value_2024": value_2024, "note_reference": ""}
    if (
        len(grouped_numbers) == 1
        and len(simple_groups) == 2
        and all(item[1] is not None and 100 <= abs(int(item[1])) <= 999 for item in simple_groups)
        and all(len(re.sub(r"\D", "", str(item[0]))) == 3 for item in simple_groups)
    ):
        raw_2025, value_2025 = simple_groups[0]
        raw_2024, value_2024 = simple_groups[1]
        return {"raw_2025": raw_2025, "value_2025": value_2025, "raw_2024": raw_2024, "value_2024": value_2024, "note_reference": ""}
    if len(grouped_numbers) >= 2:
        raw_2025, value_2025 = grouped_numbers[-2]
        raw_2024, value_2024 = grouped_numbers[-1]
        note_reference = ""
        if len(grouped_numbers) >= 3 and grouped_numbers[0][1] is not None and 0 < abs(int(grouped_numbers[0][1])) <= 99:
            note_reference = grouped_numbers[0][0]
        return {"raw_2025": raw_2025, "value_2025": value_2025, "raw_2024": raw_2024, "value_2024": value_2024, "note_reference": note_reference}
    if len(grouped_numbers) == 1:
        raw_2025, value_2025 = grouped_numbers[0]
        return {"raw_2025": raw_2025, "value_2025": value_2025, "raw_2024": "", "value_2024": None, "note_reference": ""}
    return {"raw_2025": "", "value_2025": None, "raw_2024": "", "value_2024": None, "note_reference": ""}


